      "Add the chicken pieces to the marinade, ensuring they are evenly coated (3 minutes).",
      "Cover the bowl and let the chicken marinate in the refrigerator for at least 2 hours, but preferably overnight, to allow the flavors to meld (3 minutes).",
      "Heat the vegetable oil in a large skillet or frying pan over medium-high heat (3 minutes).",
      "Remove the chicken pieces from the marinade, reserving the marinade for later use (3 minutes).",
      "Place the chicken in the skillet and cook until browned on all sides, about 5–7 minutes per side (3 minutes).",
      "Once the chicken is browned, reduce the heat to medium and add the reserved marinade to the skillet (3 minutes).",
      "Cover the skillet and let the chicken simmer in the marinade for about 20–25 minutes, or until the chicken is cooked through and tender (3 minutes).",
