      "Gently simmer the chickpeas with the 9 cups water (generously salted) and the tablespoon of oil until very soft, but still whole (about 3 hours, or 10 minutes + cooling time if using a pressure cooker) (3 minutes).",
      "Drain the chickpeas, and reserve a few cups of the cooking liquid (you will need it later) (3 minutes).",
      "Rinse the chickpeas with plenty of cold water (3 minutes).",
      "While doing so, gently rub them between your hands to release the skins—they should float away with the rinsing water (3 minutes).",
