      "Using a food processor (or other means), mix the lemon juice with the tahini (3 minutes).",
      "Purée (or mash) the chickpeas in batches, using the lemon juice and tahini mixture, the olive oil, and the cooking liquid as required to maintain the desired consistency (add the garlic to the batch with the olive oil, and process until smooth) (3 minutes).",
