      "Cover with salt and set aside for at least 4 hours (24 is better) (3 minutes).",
      "Dry-roast the yellow mustard seeds, fenugreek seeds, star anise, and chopped chilis in a pan over high heat, shaking constantly—don't burn them! (3 minutes).",
      "Strain the juice from the lemons into a small saucepan, add the turmeric, ginger and sugar, and simmer for 2–3 minutes until the sugar has dissolved (3 minutes).",
      "If there isn't enough juice, add 1–2 tablespoons water (3 minutes).",
      "Add the spices and sugar mixture to the bowl of lemons, and mix together well (3 minutes).",
      "Pack into a pint jar, pressing the pieces in if needed, to ensure that the liquid covers all the lemon pieces (3 minutes).",
      "Set aside to mature for 1 month."
